"""Legacy-compatible numeric division."""

from __future__ import annotations

import math
from typing import Any


def _coerce_numeric(value: Any) -> float:
    """Apply the legacy numeric coercion rules."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return 0.0

    try:
        return float(value)
    except OverflowError:
        # Preserve a numeric value's sign when converting an oversized integer.
        return math.inf if value >= 0 else -math.inf


def safe_div(a: Any, b: Any) -> tuple[float, list[str]]:
    """Divide using CRMScript semantics for numeric division by zero."""
    numerator = _coerce_numeric(a)
    denominator = _coerce_numeric(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    return numerator / denominator, []
